import { existsSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const manifestPath = join(repoRoot, "src-tauri", "Cargo.toml");
const appGradlePath = join(
  repoRoot,
  "src-tauri",
  "gen",
  "android",
  "app",
  "tauri.build.gradle.kts",
);
const outputPath = join(
  repoRoot,
  "src-tauri",
  "gen",
  "android",
  "tauri.settings.gradle",
);

const metadataResult = spawnSync(
  "cargo",
  [
    "metadata",
    "--locked",
    "--manifest-path",
    manifestPath,
    "--format-version",
    "1",
  ],
  {
    cwd: repoRoot,
    encoding: "utf8",
    maxBuffer: 32 * 1024 * 1024,
  },
);

if (metadataResult.error) {
  throw metadataResult.error;
}
if (metadataResult.status !== 0) {
  throw new Error(
    `cargo metadata failed with exit code ${metadataResult.status}: ${metadataResult.stderr.trim()}`,
  );
}

const metadata = JSON.parse(metadataResult.stdout);
const rootId = metadata.resolve?.root;
const rootNode = metadata.resolve?.nodes?.find((node) => node.id === rootId);
if (!rootId || !rootNode) {
  throw new Error("cargo metadata did not identify the application package");
}

const packageById = new Map(metadata.packages.map((pkg) => [pkg.id, pkg]));
const appGradle = readFileSync(appGradlePath, "utf8");
const requiredModules = Array.from(
  appGradle.matchAll(
    /implementation\s*\(\s*project\s*\(\s*["']:([A-Za-z0-9._-]+)["']\s*\)\s*\)/g,
  ),
  (match) => match[1],
);

if (
  requiredModules.length === 0 ||
  new Set(requiredModules).size !== requiredModules.length
) {
  throw new Error(
    "tracked tauri.build.gradle.kts has no modules or contains duplicate modules",
  );
}

const moduleDirectory = (moduleName) => {
  const packageName = moduleName === "tauri-android" ? "tauri" : moduleName;
  if (packageName !== "tauri" && !packageName.startsWith("tauri-plugin-")) {
    throw new Error(`unsupported Android project dependency: ${moduleName}`);
  }

  const matchingDependencies = rootNode.deps.filter((dependency) => {
    const pkg = packageById.get(dependency.pkg);
    const isRuntimeDependency = dependency.dep_kinds.some(
      ({ kind }) => kind === null,
    );
    return pkg?.name === packageName && isRuntimeDependency;
  });
  if (matchingDependencies.length !== 1) {
    throw new Error(
      `expected one direct runtime dependency for ${moduleName}, found ${matchingDependencies.length}`,
    );
  }

  const pkg = packageById.get(matchingDependencies[0].pkg);
  const packageRoot = dirname(pkg.manifest_path);
  const androidDirectory =
    packageName === "tauri"
      ? join(packageRoot, "mobile", "android")
      : join(packageRoot, "android");
  if (
    !existsSync(androidDirectory) ||
    !statSync(androidDirectory).isDirectory()
  ) {
    throw new Error(`Android library directory is missing for ${moduleName}`);
  }
  return androidDirectory;
};

const quoteGroovy = (value) =>
  `'${value.replaceAll("\\", "\\\\").replaceAll("'", "\\'")}'`;
const lines = [
  "// THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.",
];
for (const moduleName of requiredModules) {
  const androidDirectory = moduleDirectory(moduleName);
  lines.push(`include ':${moduleName}'`);
  lines.push(
    `project(':${moduleName}').projectDir = new File(${quoteGroovy(androidDirectory)})`,
  );
}

writeFileSync(outputPath, `${lines.join("\n")}\n`, "utf8");
console.log(
  `Generated Android settings for ${requiredModules.length} Tauri modules.`,
);
